import{_ as a,o as i,c as e,a1 as t}from"./chunks/framework.DIevSSiF.js";const c=JSON.parse('{"title":"Quick start","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quickstart.md","filePath":"guide/quickstart.md"}'),n={name:"guide/quickstart.md"};function h(l,s,p,o,r,d){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h1><p>Shadow has one loop: create or read a project plan, claim a checkpoint on this computer, do only that claimed work, then leave proof or a precise wake.</p><h2 id="_1-create-or-open-the-plan" tabindex="-1">1. Create or open the plan <a class="header-anchor" href="#_1-create-or-open-the-plan" aria-label="Permalink to &quot;1. Create or open the plan&quot;">​</a></h2><p>From a Git project with no <code>PLAN.md</code> yet:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shadow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --here</span></span></code></pre></div><p><code>shadow init --here</code> prints <code>created local PLAN.md: &lt;path&gt;</code> — a machine-local plan under <code>~/.shadow/plans/&lt;project&gt;/PLAN.md</code>, never a file inside this repo. Open and lint that exact printed path, giving this checkout as its source:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$EDITOR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.shadow/plans/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/PLAN.md</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shadow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.shadow/plans/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">projec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/PLAN.md</span></span></code></pre></div><p>Fill the generated Brief, then add a task whose proof is executable in this checkout. For example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- [pending] document a verifiable change ~ab12 | proof: cmd python3 -m unittest discover -s tests</span></span></code></pre></div><p>Use the repository&#39;s real test command and replace the illustrative row text; <code>npm test</code> is not a Shadow default. Existing plans should be read and edited in place rather than initialized over.</p><h2 id="_2-read-the-computer-board-and-claim-one-row" tabindex="-1">2. Read the computer board and claim one row <a class="header-anchor" href="#_2-read-the-computer-board-and-claim-one-row" aria-label="Permalink to &quot;2. Read the computer board and claim one row&quot;">​</a></h2><p>Choose a stable seat name and read from any directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shadow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --by</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-seat</span></span></code></pre></div><p>Copy the exact <code>shadow throw</code> command printed for a reachable row — it names the entity id, not a repo path. Quote ids such as <code>~ab12</code> in zsh:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shadow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> throw</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --entity</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">entity-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;~ab12&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --by</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-seat</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shadow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> amp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --by</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-seat</span></span></code></pre></div><p>The root board at <code>~/.shadow</code> owns the claim and lease. The project <code>PLAN.md</code> still owns the row text, proof, and evidence; the board never copies them. When the current branch tracks configured <code>origin</code>, <code>shadow throw</code> also confirms one deterministic remote coordination lock before printing the work packet. Its closed public receipt names the row, lease, and exact PLAN objects; it is not another task or proof board. With no configured origin upstream, claiming stays local-only.</p><h2 id="_3-work-through-a-bounded-host" tabindex="-1">3. Work through a bounded host <a class="header-anchor" href="#_3-work-through-a-bounded-host" aria-label="Permalink to &quot;3. Work through a bounded host&quot;">​</a></h2><p>Use the returned packet yourself, or run a sealed host only over the exact claimed paths:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shadow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --task-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/task.md</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --task-id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> focused-fix</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --allowed-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/fix.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --allowed-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/test_shadow_init.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .shadow/evidence/focused-fix.json</span></span></code></pre></div><p>Review the diff and reproduce the proof locally. A host receipt is evidence, not acceptance by itself.</p><h2 id="_4-close-the-loop" tabindex="-1">4. Close the loop <a class="header-anchor" href="#_4-close-the-loop" aria-label="Permalink to &quot;4. Close the loop&quot;">​</a></h2><p>For a passing <code>cmd</code> proof, use the only flip path:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shadow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> accept</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --row</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;~ab12&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --by</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-seat</span></span></code></pre></div><p>For a remotely coordinated claim, ordinary accept publishes the completed PLAN, records the completed tombstone, and then releases the local claim. <code>shadow accept --no-push</code> retains both the local claim and remote lock until a later ordinary accept can publish and finish that ordering.</p><p>For a person-observed <code>read</code> or <code>gate</code> proof, append the result to the plan and return the claim. For blocked work, append one Deferred wake naming the exact condition before returning it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shadow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --row</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;~ab12&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --by</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-seat</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shadow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --in-flight</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>At the end of the chat, render an <strong>Ongoing tasks</strong> footer from that fresh in-flight projection: claims first, then the current seat&#39;s reachable and waiting rows, with owner, state, proof, and wake. Print <code>Active tasks: none</code> only when the board has no ongoing work. This is a view of <code>~/.shadow</code>, never a second queue.</p><h2 id="next-references" tabindex="-1">Next references <a class="header-anchor" href="#next-references" aria-label="Permalink to &quot;Next references&quot;">​</a></h2><ul><li><a href="./../reference/commands.html">Commands</a> for every flag and exit boundary.</li><li><a href="./../reference/host-integration.html">Host integration</a> for cold-start behavior.</li><li><a href="./other-computer-handoff.html">Other-computer handoff</a> for a fresh machine.</li></ul>`,29)])])}const F=a(n,[["render",h]]);export{c as __pageData,F as default};
